/* Elements
0  N
1  Ar
2  He
3  H
4  O
5  C
*/

// Species
#define H2_ID 0
#define H_ID 1
#define O2_ID 2
#define O_ID 3
#define OH_ID 4
#define HO2_ID 5
#define H2O_ID 6
#define H2O2_ID 7
#define N_ID 8
#define NO_ID 9
#define NO2_ID 10
#define N2O_ID 11
#define NH_ID 12
#define NH2_ID 13
#define N2H_ID 14
#define NH3_ID 15
#define HNO_ID 16
#define H2NO_ID 17
#define N2_ID 18
#define AR_ID 19
#define HE_ID 20

#define NUM_GAS_ELEMENTS 6   // Elements in the homogeneous phase
#define NUM_GAS_SPECIES 21   // Species in the homogeneous phase
#define NUM_GAS_REACTIONS 64 // Reactions in the homogeneous phase

#define SITE_DENSITY 0.000000E+00 // mol/cm^2

#define NUM_SURFACE_ELEMENTS 0  // Additional elements in heterogeneous phase
#define NUM_SURFACE_SPECIES 0   // Species in the heterogeneous phase
#define NUM_SURFACE_REACTIONS 0 // Reactions in the heterogeneous phase

#define NUM_ELEMENTS (NUM_GAS_ELEMENTS + NUM_SURFACE_ELEMENTS)
#define NUM_SPECIES (NUM_GAS_SPECIES + NUM_SURFACE_SPECIES)
#define NUM_REACTIONS (NUM_GAS_REACTIONS + NUM_SURFACE_REACTIONS)

#define NUM_IONS 0

#define NUM_FIT 4

