                 3.71690050e-11 * T3;
    // species 6: H2O
    species[6] = -2.03643410e-03 + 1.30408042e-05 * T - 1.64639119e-08 * T2 +
                 7.08791268e-12 * T3;
    // species 7: H2O2
    species[7] = -5.42822417e-04 + 3.34671402e-05 * T - 6.47312439e-08 * T2 +
                 3.44981745e-11 * T3;
    // species 8: N
    species[8] = -2.18001800e-05 + 1.08410580e-07 * T - 1.69426800e-10 * T2 +
                 8.39961600e-14 * T3;
    // species 9: NO
